for mode,omit,verify,scene in [(3,1,0,'standard'),(3,1,0,'long'),(3,0,0,'standard'),(3,0,0,'long'),(3,1,1024,'standard'),(3,1,1024,'long'),(0,1,0,'standard')]:
 label=f'{scene}-m{mode}-o{omit}-v{verify}';q=read(s/f'guard-publication-replay-{label}/report.json');c=read(s/f'guard-publication-compare-{label}.json')
