 assert q['unsafe_code']==mode and q['omit_guard_publication']==omit and q['leaf_features']==128 and q['code_lookup']==0 and q['verify_aot']==verify and q['execution_limits']==[512,16,8,512]
 assert q['wasm_sha256']==archives['guard-publication-candidate']['files']['eka2l1.wasm']and q['loader_sha256']==archives['guard-publication-candidate']['files']['eka2l1.js']
 e['replays'][label]={'report':q,'comparison':c}
