e['timings']={};complete=True
for scene,b in [('long','a'),('standard','a'),('long','b'),('standard','b')]:
 path=s/f'guard-publication-timing-{scene}-{b}/measurements.json';hp=s/f'guard-publication-timing-{scene}-{b}-host.json'
 if not path.exists()or not hp.exists():complete=False;continue
 rows=read(path);host=read(hp);assert len(rows)==6 and not host['foreign_jobs']and host['returncode']==0
 assert len({tuple(x['measurement'][k]for k in ['first_instructions','last_instructions','presentations'])for x in rows})==1
 for x in rows:
  mode=x['name'].rsplit('-',1)[0];archive=archives['unsafe-default-candidate'if mode=='baseline'else'guard-publication-candidate']
  assert x['wasm_sha256']==archive['files']['eka2l1.wasm']and x['loader_sha256']==archive['files']['eka2l1.js']
  assert x['unsafe_code']==3 and x['leaf_features']==128 and x['code_lookup']==0 and x['execution_limits']==[512,16,8,512]and not x['measurement']['detailed']
  assert x['omit_guard_publication']==(None if mode=='baseline'else int(mode=='candidate'))
 vals={n:[x['measurement']['wall_seconds']for x in rows if x['name'].startswith(n)]for n in ['control','candidate','baseline']};means={n:sum(v)/2 for n,v in vals.items()}
 pairs={n:[(c/v-1)*100 for c,v in zip(vals[n],vals['candidate'])]for n in ['control','baseline']}
 gains={n:(means[n]/means['candidate']-1)*100 for n in ['control','baseline']}
 e['timings'][scene+'-'+b]={'rows':rows,'host':host,'means':means,'gains_percent':gains,'half_pairs_percent':pairs}
