p=d/'GUARD_PUBLICATION_RESULTS.md';prefix=p.read_text().split('\n## Full acceptance')[0]
lines=['','## Full acceptance','','All 176 compiler tests pass, including 48 real-runner publication checks and the','existing budget, callback, remap, cache and deliberate stale-code tests. Fresh','mode-3/feature-128 native fault comparisons match in all 46,016 cases. That','direct-instruction probe covers emitted operations; the publication option is','exercised by the focused real runner and browser replays.','','Both new-binary modes exactly match standard 1,600 images / 4,656,051 stereo','PCM frames and longer 360 images / 2,832,756 PCM frames, including guest records.','The candidate also passes both interpreter-checked routes at stride 1024.','Explicit mode 0 with the option selected passes standard exact replay; its','interval publication remains enabled. Configuration readback and rejection of','post-initialization changes are checked in those runs.','','The 24-observation timing plan compares candidate, matching control and the','untouched delivered archive, with literal feature 128, mode 3, lookup 0 and','limits 512/16/8/512 fixed. All samples, actual orders and passive host readings','are retained. The old archive has no publication-selector API; no selector is','sent to it, and its original publishing runtime is the baseline.']
if complete:
 lines+=['','| Route/batch | Matching seconds | Candidate seconds | Live seconds | vs matching | vs live |','| --- | ---: | ---: | ---: | ---: | ---: |']
 for k,v in e['timings'].items():
  m=v['means'];g=v['gains_percent'];lines.append(f"| {k} | {m['control']:.5f} | {m['candidate']:.5f} | {m['baseline']:.5f} | {g['control']:+.2f}% | {g['baseline']:+.2f}% |")
 lines+=['','All 24 observations are retained. Review is pending; no promotion is automatic.']
else:lines+=['','Acceptance passes. Timings are pending; no speed claim or promotion.']
p.write_text(prefix+'\n'.join(lines)+'\n')
print(e['status'],json.dumps({k:{x:v[x]for x in ['means','gains_percent','half_pairs_percent']}for k,v in e['timings'].items()},indent=2))

