  q=json.loads((s/'guard-publication-acceptance-state.json').read_text())
  if q['phase']=='failure':raise RuntimeError('Acceptance stopped: '+str(q))
  time.sleep(3)
 phase('recording_acceptance');run('record_guard_publication.py');commit('Verify opt-in guard publication removal against native execution')
 phase('serial_timing');run('guarded_guard_publication_timings.py')
 phase('recording_timings');run('record_guard_publication.py');commit('Retain all guard publication timing samples and host context')
